1	//! Manifest reading and MatrixReport assembly for `callisto matrix`.
2	//! Private helpers only -- the public entry point is
3	//! `crate::commands::matrix::matrix`.
4	
5	/// Per-triple CI scheduling attributes for the 18 triples
6	/// `crate::napi::triple_to_role` recognises today. This table is NEW code:
7	/// `triple_to_role`'s `ManifestRole::Platform` carries only platform/arch/abi
8	/// and has no concept of hostRunner/useCross, so this cannot be derived from
9	/// it. Returns `None` for any triple `triple_to_role` does not recognise --
10	/// callers must treat that as the AC-011 diagnostic path, never a silent
11	/// default.
12	pub(crate) fn triple_host_runner_use_cross(triple: &str) -> Option<(&'static str, bool)> {
13	    Some(match triple {
14	        "aarch64-apple-darwin" => ("macos-latest", false),
15	        "x86_64-apple-darwin" => ("macos-13", false),
16	        "x86_64-unknown-linux-gnu" => ("ubuntu-latest", false),
17	        "x86_64-unknown-linux-musl" => ("ubuntu-latest", true),
18	        "aarch64-unknown-linux-gnu" => ("ubuntu-latest", true),
19	        "aarch64-unknown-linux-musl" => ("ubuntu-latest", true),
20	        "x86_64-pc-windows-msvc" => ("windows-latest", false),
21	        "i686-pc-windows-msvc" => ("windows-latest", false),
22	        "aarch64-pc-windows-msvc" => ("windows-latest", false),
23	        "armv7-unknown-linux-gnueabihf" => ("ubuntu-latest", true),
24	        "x86_64-unknown-freebsd" => ("ubuntu-latest", true),
25	        "aarch64-linux-android" => ("ubuntu-latest", true),
26	        "armv7-linux-androideabi" => ("ubuntu-latest", true),
27	        "riscv64gc-unknown-linux-gnu" => ("ubuntu-latest", true),
28	        "powerpc64le-unknown-linux-gnu" => ("ubuntu-latest", true),
29	        "s390x-unknown-linux-gnu" => ("ubuntu-latest", true),
30	        "wasm32-wasip1" => ("ubuntu-latest", false),
31	        "wasm32-unknown-unknown" => ("ubuntu-latest", false),
32	        _ => return None,
33	    })
34	}
35	
36	/// AC-001: artifactName embeds the package's own (already workspace-unique)
37	/// name alongside the triple, so two packages sharing a triple never
38	/// collide once fed through `unique_by(.artifactName)` in
39	/// `.github/actions/callisto-action/action.yml`.
40	pub(crate) fn artifact_name_for_package_triple(package_name: &str, triple: &str) -> String {
41	    format!("native-{package_name}-{triple}")
42	}
43	
44	use std::path::Path;
45	
46	use callisto_model::{ManifestError, ManifestFormat, ManifestRole, PlatformTarget};
47	
48	use crate::error::GraphError;
49	use crate::napi::triple_to_role;
50	
51	/// Result of reading the `napi.targets` field from a package.json. Distinct
52	/// from `Option<Vec<String>>` so AC-001b (present-but-empty vs absent) is a
53	/// type-level distinction, not a magic-empty-vec convention.
54	#[derive(Clone, Debug, PartialEq, Eq)]
55	pub(crate) enum NapiTargetsField {
56	    Absent,
57	    Present(Vec<String>),
58	}
59	
60	/// Reads and parses `pkg_json_path` as JSON, if it exists. `Ok(None)` when
61	/// the file is absent -- not every package has a `package.json`.
62	///
63	/// Callers needing more than one field out of the same `package.json` (e.g.
64	/// both `napi.targets` and `engines.node`, see `build_matrix_report`) must
65	/// call this once and pass the resulting `Value` to each field-extraction
66	/// function (`read_napi_targets`, `read_engines_node`) rather than letting
67	/// each one independently re-read and re-parse the file from disk.
68	pub(crate) fn parse_package_json(pkg_json_path: &Path) -> Result<Option<serde_json::Value>, GraphError> {
69	    if !pkg_json_path.exists() {
70	        return Ok(None);
71	    }
72	    let content = std::fs::read_to_string(pkg_json_path).map_err(|e| {
73	        GraphError::Manifest(ManifestError::Read {
74	            path: pkg_json_path.to_path_buf(),
75	            message: e.to_string(),
76	        })
77	    })?;
78	    let val: serde_json::Value = serde_json::from_str(&content).map_err(|e| {
79	        GraphError::Manifest(ManifestError::Parse {
80	            path: pkg_json_path.to_path_buf(),
81	            format: ManifestFormat::PackageJson,
82	            message: e.to_string(),
83	        })
84	    })?;
85	    Ok(Some(val))
86	}
87	
88	/// Extracts `napi.targets` from an already-parsed `package.json` value (see
89	/// `parse_package_json`). A missing `napi` key or missing `napi.targets` key
90	/// is `Absent` (AC-003: no platformTargets entry). A present `napi.targets`
91	/// that is not a JSON array of strings is a hard error (AC-010c) -- unlike
92	/// `NapiTargetsIndex::load`, which silently drops non-array values.
93	pub(crate) fn read_napi_targets(pkg_json_path: &Path, val: &serde_json::Value) -> Result<NapiTargetsField, GraphError> {
94	    let Some(napi) = val.get("napi") else {
95	        return Ok(NapiTargetsField::Absent);
96	    };
97	    let Some(targets) = napi.get("targets") else {
98	        return Ok(NapiTargetsField::Absent);
99	    };
100	
101	    let arr = targets.as_array().ok_or_else(|| {
102	        GraphError::Manifest(ManifestError::Parse {
103	            path: pkg_json_path.to_path_buf(),
104	            format: ManifestFormat::PackageJson,
105	            message: "napi.targets must be a JSON array of strings".to_string(),
106	        })
107	    })?;
108	
109	    let mut out = Vec::with_capacity(arr.len());
110	    for item in arr {
111	        let s = item.as_str().ok_or_else(|| {
112	            GraphError::Manifest(ManifestError::Parse {
113	                path: pkg_json_path.to_path_buf(),
114	                format: ManifestFormat::PackageJson,
115	                message: "napi.targets entries must all be strings".to_string(),
116	            })
117	        })?;
118	        out.push(s.to_string());
119	    }
120	    Ok(NapiTargetsField::Present(out))
121	}
122	
123	/// Builds a PlatformTarget for `triple`, combining `triple_to_role`'s
124	/// platform/arch/abi with this module's hostRunner/useCross/artifactName
125	/// table. Returns `None` when `triple` is not recognised by either --
126	/// callers must route that case to an UnrecognisedPlatformTriple diagnostic
127	/// (AC-011) rather than treating it as an error.
128	pub(crate) fn build_platform_target(triple: &str, package_dir: &str, package_name: &str) -> Option<PlatformTarget> {
129	    let ManifestRole::Platform { platform, arch, abi } = triple_to_role(triple)? else {
130	        return None;
131	    };
132	    let (host_runner, use_cross) = triple_host_runner_use_cross(triple)?;
133	    Some(PlatformTarget {
134	        triple: triple.to_string(),
135	        platform,
136	        arch,
137	        abi,
138	        host_runner: host_runner.to_string(),
139	        use_cross,
140	        artifact_name: artifact_name_for_package_triple(package_name, triple),
141	        package_dir: package_dir.to_string(),
142	        package_name: package_name.to_string(),
143	    })
144	}
145	
146	/// Reads and parses `pyproject_path` as TOML, if it exists. `Ok(None)` when
147	/// the file is absent -- not every package has a `pyproject.toml`.
148	///
149	/// Callers needing more than one field out of the same `pyproject.toml`
150	/// (e.g. both `[tool.maturin].targets` and `requires-python`, see
151	/// `build_matrix_report`) must call this once and pass the resulting
152	/// `Value` to each field-extraction function (`read_maturin_targets`,
153	/// `read_requires_python`) rather than letting each one independently
154	/// re-read and re-parse the file from disk.
155	pub(crate) fn parse_pyproject_toml(pyproject_path: &Path) -> Result<Option<toml::Value>, GraphError> {
156	    if !pyproject_path.exists() {
157	        return Ok(None);
158	    }
159	    let content = std::fs::read_to_string(pyproject_path).map_err(|e| {
160	        GraphError::Manifest(ManifestError::Read {
161	            path: pyproject_path.to_path_buf(),
162	            message: e.to_string(),
163	        })
164	    })?;
165	    let val: toml::Value = content.parse().map_err(|e: toml::de::Error| {
166	        GraphError::Manifest(ManifestError::Parse {
167	            path: pyproject_path.to_path_buf(),
168	            format: ManifestFormat::PyprojectToml,
169	            message: e.to_string(),
170	        })
171	    })?;
172	    Ok(Some(val))
173	}
174	
175	/// Extracts `[tool.maturin].targets` from an already-parsed `pyproject.toml`
176	/// value (see `parse_pyproject_toml`). Returns `Ok(None)` when the table or
177	/// field is absent (AC-003: no platformTargets entry). A present value that
178	/// is not a TOML array of strings is a hard error (AC-010c).
179	pub(crate) fn read_maturin_targets(
180	    pyproject_path: &Path,
181	    val: &toml::Value,
182	) -> Result<Option<Vec<String>>, GraphError> {
183	    let Some(targets) = val
184	        .get("tool")
185	        .and_then(|t| t.get("maturin"))
186	        .and_then(|m| m.get("targets"))
187	    else {
188	        return Ok(None);
189	    };
190	
191	    let arr = targets.as_array().ok_or_else(|| {
192	        GraphError::Manifest(ManifestError::Parse {
193	            path: pyproject_path.to_path_buf(),
194	            format: ManifestFormat::PyprojectToml,
195	            message: "[tool.maturin].targets must be an array of strings".to_string(),
196	        })
197	    })?;
198	
199	    let mut out = Vec::with_capacity(arr.len());
200	    for item in arr {
201	        let s = item.as_str().ok_or_else(|| {
202	            GraphError::Manifest(ManifestError::Parse {
203	                path: pyproject_path.to_path_buf(),
204	                format: ManifestFormat::PyprojectToml,
205	                message: "[tool.maturin].targets entries must all be strings".to_string(),
206	            })
207	        })?;
208	        out.push(s.to_string());
209	    }
210	    Ok(Some(out))
211	}
212	
213	/// Extracts `engines.node` as a raw string from an already-parsed
214	/// `package.json` value (see `parse_package_json`). `Ok(None)` when absent;
215	/// `Err` when present but not a JSON string.
216	pub(crate) fn read_engines_node(pkg_json_path: &Path, val: &serde_json::Value) -> Result<Option<String>, GraphError> {
217	    let Some(node) = val.get("engines").and_then(|e| e.get("node")) else {
218	        return Ok(None);
219	    };
220	    let s = node.as_str().ok_or_else(|| {
221	        GraphError::Manifest(ManifestError::Parse {
222	            path: pkg_json_path.to_path_buf(),
223	            format: ManifestFormat::PackageJson,
224	            message: "engines.node must be a string".to_string(),
225	        })
226	    })?;
227	    Ok(Some(s.to_string()))
228	}
