249	/// Reads napi.targets and [tool.maturin].targets from `package_dir_abs`
250	/// (the package's on-disk directory) and determines which single source (if
251	/// any) declares platform targets.
252	///
253	/// `pkg_json_val`/`pyproject_val` are the package's already-parsed manifest
254	/// values (see `parse_package_json`/`parse_pyproject_toml`), `None` when the
255	/// corresponding file doesn't exist -- shared with `assemble_runtime_versions`
256	/// so `build_matrix_report` parses each file at most once per package.
257	///
258	/// - Neither declared: `Ok(None)` (AC-003).
259	/// - Both declared: `Err(GraphError::ConflictingPlatformTargetSources)` (AC-017).
260	/// - Exactly one declared (even as an explicitly empty array, AC-001b):
261	///   `Ok(Some((kind, source, triples)))`.
262	pub(crate) fn select_platform_target_source(
263	    package_dir_abs: &Path,
264	    package_id: &PackageId,
265	    pkg_json_val: Option<&serde_json::Value>,
266	    pyproject_val: Option<&toml::Value>,
267	) -> Result<Option<(PlatformTargetKind, String, Vec<String>)>, GraphError> {
268	    let napi_path = package_dir_abs.join("package.json");
269	    let napi_field = match pkg_json_val {
270	        Some(val) => read_napi_targets(&napi_path, val)?,
271	        None => NapiTargetsField::Absent,
272	    };
273	
274	    let maturin_path = package_dir_abs.join("pyproject.toml");
275	    let maturin_targets = match pyproject_val {
276	        Some(val) => read_maturin_targets(&maturin_path, val)?,
277	        None => None,
278	    };
279	
280	    match (napi_field, maturin_targets) {
281	        (NapiTargetsField::Present(_), Some(_)) => Err(GraphError::ConflictingPlatformTargetSources {
282	            package: package_id.clone(),
283	            napi_source: "napi.targets",
284	            maturin_source: "[tool.maturin].targets",
285	        }),
286	        (NapiTargetsField::Present(triples), None) => {
287	            Ok(Some((PlatformTargetKind::Napi, "napi.targets".to_string(), triples)))
288	        }
289	        (NapiTargetsField::Absent, Some(triples)) => Ok(Some((
290	            PlatformTargetKind::Maturin,
291	            "[tool.maturin].targets".to_string(),
292	            triples,
293	        ))),
294	        (NapiTargetsField::Absent, None) => Ok(None),
295	    }
296	}
