298	use callisto_model::{Diagnostic, DiagnosticCode, DiagnosticSeverity, PlatformTargetGroup};
299	
300	/// Calls `select_platform_target_source` and, when a source is present,
301	/// builds a PlatformTarget for every declared triple (AC-001, AC-002),
302	/// excluding any triple `build_platform_target` does not recognise and
303	/// pushing an `UnrecognisedPlatformTriple` warning Diagnostic for each one
304	/// instead (AC-011). `group.targets` is sorted ascending by triple string
305	/// (AC-009) before returning.
306	pub(crate) fn assemble_platform_target_group(
307	    package_dir_abs: &Path,
308	    package_dir_rel: &str,
309	    package_name: &str,
310	    package_id: &PackageId,
311	    pkg_json_val: Option<&serde_json::Value>,
312	    pyproject_val: Option<&toml::Value>,
313	) -> Result<(Option<PlatformTargetGroup>, Vec<Diagnostic>), GraphError> {
314	    let Some((kind, source, triples)) =
315	        select_platform_target_source(package_dir_abs, package_id, pkg_json_val, pyproject_val)?
316	    else {
317	        return Ok((None, Vec::new()));
318	    };
319	
320	    let mut targets = Vec::new();
321	    let mut diagnostics = Vec::new();
322	    let mut seen_triples = std::collections::BTreeSet::new();
323	    for triple in &triples {
324	        if !seen_triples.insert(triple.as_str()) {
325	            diagnostics.push(Diagnostic {
326	                code: DiagnosticCode::DuplicatePlatformTriple,
327	                severity: DiagnosticSeverity::Warning,
328	                message: format!(
329	                    "package `{package_name}` declares duplicate platform triple `{triple}` in `{source}`; only the first occurrence is used"
330	                ),
331	                package: Some(package_id.clone()),
332	                path: None,
333	                escalated_by: None,
334	                governed_by: None,
335	            });
336	            continue;
337	        }
338	        match build_platform_target(triple, package_dir_rel, package_name) {
339	            Some(t) => targets.push(t),
340	            None => diagnostics.push(Diagnostic {
341	                code: DiagnosticCode::UnrecognisedPlatformTriple,
342	                severity: DiagnosticSeverity::Warning,
343	                message: format!(
344	                    "package `{package_name}` declares unrecognised platform triple `{triple}` in `{source}`"
345	                ),
346	                package: Some(package_id.clone()),
347	                path: None,
348	                escalated_by: None,
349	                governed_by: None,
350	            }),
351	        }
352	    }
353	    targets.sort_by(|a, b| a.triple.cmp(&b.triple));
354	
355	    Ok((Some(PlatformTargetGroup { kind, source, targets }), diagnostics))
356	}
