363	/// One registered package's identity and on-disk location, adapted from a
364	/// real `Workspace` by `crate::commands::matrix::matrix` (or built directly
365	/// by tests).
366	pub(crate) struct MatrixPackageInput {
367	    pub id: PackageId,
368	    /// Absolute path to the package's directory (used for manifest reads).
369	    pub dir_abs: PathBuf,
370	    /// Workspace-root-relative path string, stored verbatim on each
371	    /// PlatformTarget.package_dir.
372	    pub dir_rel: String,
373	    pub name: String,
374	}
375	
376	/// Reads engines.node (npm) and requires-python (python) from
377	/// `package_dir_abs`'s already-parsed manifest values, in that order, so
378	/// callers preserve the npm-before-python ordering AC-005b requires without
379	/// a separate sort step. `pkg_json_val`/`pyproject_val` are shared with
380	/// `assemble_platform_target_group` (see `select_platform_target_source`'s
381	/// doc comment) so `build_matrix_report` parses each file at most once per
382	/// package.
383	pub(crate) fn assemble_runtime_versions(
384	    package_dir_abs: &Path,
385	    pkg_json_val: Option<&serde_json::Value>,
386	    pyproject_val: Option<&toml::Value>,
387	) -> Result<Vec<RuntimeVersionEntry>, GraphError> {
388	    let mut entries = Vec::new();
389	
390	    let pkg_json = package_dir_abs.join("package.json");
391	    if let Some(val) = pkg_json_val {
392	        if let Some(range) = read_engines_node(&pkg_json, val)? {
393	            entries.push(RuntimeVersionEntry {
394	                ecosystem: RuntimeEcosystem::Npm,
395	                field: "engines.node".to_string(),
396	                range,
397	            });
398	        }
399	    }
400	
401	    let pyproject = package_dir_abs.join("pyproject.toml");
402	    if let Some(val) = pyproject_val {
403	        if let Some(range) = read_requires_python(&pyproject, val)? {
404	            entries.push(RuntimeVersionEntry {
405	                ecosystem: RuntimeEcosystem::Python,
406	                field: "requires-python".to_string(),
407	                range,
408	            });
409	        }
410	    }
411	
412	    Ok(entries)
413	}
414	
415	/// Assembles the full MatrixReport for `packages`. Map keys are each
416	/// package's bare name (AC-009's BTreeMap ordering comes from this for free);
417	/// a package contributes no platformTargets entry when it declares neither
418	/// napi.targets nor [tool.maturin].targets, and no runtimeVersions entry when
419	/// it declares neither engines.node nor requires-python.
420	///
421	/// Each package's `package.json`/`pyproject.toml` is read and parsed at most
422	/// once here and the resulting value shared between the platform-target and
423	/// runtime-version extraction paths, instead of each independently
424	/// re-reading and re-parsing the same file from disk.
425	pub(crate) fn build_matrix_report(packages: &[MatrixPackageInput]) -> Result<MatrixReport, GraphError> {
426	    let mut platform_targets = BTreeMap::new();
427	    let mut runtime_versions = BTreeMap::new();
428	    let mut diagnostics = Vec::new();
429	
430	    for pkg in packages {
431	        let pkg_json_val = parse_package_json(&pkg.dir_abs.join("package.json"))?;
432	        let pyproject_val = parse_pyproject_toml(&pkg.dir_abs.join("pyproject.toml"))?;
433	
434	        let (group, diags) = assemble_platform_target_group(
435	            &pkg.dir_abs,
436	            &pkg.dir_rel,
437	            &pkg.name,
438	            &pkg.id,
439	            pkg_json_val.as_ref(),
440	            pyproject_val.as_ref(),
441	        )?;
442	        if let Some(group) = group {
443	            platform_targets.insert(pkg.name.clone(), group);
444	        }
445	        diagnostics.extend(diags);
446	
447	        let rv = assemble_runtime_versions(&pkg.dir_abs, pkg_json_val.as_ref(), pyproject_val.as_ref())?;
448	        if !rv.is_empty() {
449	            runtime_versions.insert(pkg.name.clone(), rv);
450	        }
451	    }
452	
453	    Ok(MatrixReport {
454	        schema_version: callisto_model::SCHEMA_VERSION,
455	        platform_targets,
456	        runtime_versions,
457	        diagnostics,
458	    })
459	}
