        let pyproject_val = parse_pyproject_toml(&tmp.path().join("pyproject.toml")).unwrap();

        let (group, diagnostics) = assemble_platform_target_group(
            tmp.path(),
            "native-mod",
            "native-mod",
            &pkg_id("native-mod"),
            pkg_json_val.as_ref(),
            pyproject_val.as_ref(),
        )
        .unwrap();
