file.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "verdict@1",
  "title": "Verdict",
  "description": "The axiom exit gate result. Pass or fail, with specific blockers on failure.",
  "type": "object",
  "required": ["verdict", "confidence", "verdict_summary"],
  "additionalProperties": false,
  "properties": {
    "verdict": {
      "enum": ["pass", "fail"],
      "description": "Whether the artifact meets its criteria"
    },
    "confidence": {
      "enum": ["high", "medium", "low"],
      "description": "Confidence in the verdict"
    },
    "blockers": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["criterion", "finding"],
        "additionalProperties": false,
        "properties": {
          "criterion": {
            "type": "string",
            "description": "The specific criterion that failed"
          },
          "finding": {
            "type": "string",
            "description": "What was found — specific, actionable, not generic"
          },
          "location": {
            "type": "string",
            "description": "File path and line number if applicable"
          }
        }
      },
      "description": "Required when verdict is fail. Each blocker must give the producing agent enough information to fix the issue."
    },
    "verdict_summary": {
      "type": "string",
      "maxLength": 300,
      "description": "One paragraph readable by a human or orchestrator. States what passed, what failed, and what happens next."
    },
    "artifact_type": {
      "type": "string",
      "description": "The schema ID of the artifact that was verified (e.g. spec@1)"
    },
    "retry_count": {
      "type": "integer",
      "minimum": 0,
      "description": "How many times this artifact has been through the gate. Escalate at 3."
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}
